// Uploads the built artifact to the release bucket.
const fs = require("fs");

const BUCKET = process.env.RELEASE_BUCKET || ""; // release bucket name, not recorded in this repo
const VERSION = require("./version.json").version;

function objectName(version) {
  return `app-${version}.js`;
}

async function putObject(bucket, name, body) {
  // Upload to the release bucket's S3-compatible endpoint, under the
  // versioned object name.
  const url = `${process.env.RELEASE_BUCKET_ENDPOINT}/bucket/${encodeURIComponent(bucket)}/${encodeURIComponent(name)}`;
  const res = await fetch(url, {
    method: "PUT",
    body,
    headers: {
      "content-type": "application/javascript",
      "content-length": String(body.length),
    },
  });
  if (!res.ok) {
    throw new Error(`PUT ${url} failed with status ${res.status} ${res.statusText}`);
  }
}

function main() {
  const body = fs.readFileSync("dist/app.js");
  const name = objectName(VERSION);
  if (!BUCKET) {
    throw new Error("BUCKET is not set");
  }
  return putObject(BUCKET, name, body).then(() => {
    console.log(`uploaded ${name} (${body.length} bytes)`);
  });
}

main().catch((err) => {
  console.error(err.message);
  process.exit(1);
});
